// Filter for approved campaigns only
const items = $input.all();

const approved = items.filter(item => {
  const row = item.json;
  const approvalStatus = String(row.approved || '').trim().toLowerCase();
  const status = String(row.status || '').trim().toLowerCase();

  // Must be approved and not already published
  if (approvalStatus === 'yes' && status !== 'published') {
    console.log(`✓ Will publish campaign for ${row.account_name}`);
    return true;
  }

  console.log(`Skipping ${row.account_name}: approved=${approvalStatus}, status=${status}`);
  return false;
});

console.log(`Found ${approved.length} campaigns ready to publish`);
return approved;

// Parse the campaign structure JSON
const row = $json;

let campaignStructure = {};
try {
  campaignStructure = JSON.parse(row.campaign_structure);
} catch (e) {
  console.error('Failed to parse campaign_structure:', e);
  throw new Error('Invalid campaign structure JSON');
}

console.log('Parsed campaign structure for:', row.account_name);
console.log('Ad groups:', campaignStructure.ad_groups?.length);

return {
  json: {
    ...row,
    parsed_campaign: campaignStructure,
    account_id_clean: String(row.account_id).replace(/-/g, '')
  }
};

