// Extract campaign ID from response and prepare for next step
const response = $json;
const previousData = $('Parse Campaign Structure').item.json;

let campaignId = '';
if (response.results && response.results[0] && response.results[0].resourceName) {
  // Extract campaign ID from resource name: customers/123/campaigns/456
  const match = response.results[0].resourceName.match(/campaigns\/(\d+)/);
  if (match) {
    campaignId = match[1];
  }
}

if (!campaignId) {
  throw new Error('Failed to extract campaign ID from response');
}

console.log('Created campaign with ID:', campaignId);

return {
  json: {
    ...previousData,
    campaign_id: campaignId,
    campaign_resource_name: response.results[0].resourceName
  }
};

// Set location targeting for South Africa
const data = $json;
const accountId = data.account_id_clean;
const campaignId = data.campaign_id;

// South Africa location ID = 2710
const locationId = '2710';

const requestBody = {
  operations: [{
    create: {
      campaign: `customers/${accountId}/campaigns/${campaignId}`,
      location: {
        geoTargetConstant: `geoTargetConstants/${locationId}`
      }
    }
  }]
};

return {
  json: {
    ...data,
    location_request: requestBody,
    api_endpoint: `https://googleads.googleapis.com/v22/customers/${accountId}/campaignCriteria:mutate`
  }
};

// Create ad groups for each ad group in the structure
const previousData = $('Extract Campaign ID').item.json;
const adGroups = previousData.parsed_campaign.ad_groups || [];

console.log(`Creating ${adGroups.length} ad groups`);

// Return one item per ad group
return adGroups.map((adGroup, index) => ({
  json: {
    ...previousData,
    current_ad_group: adGroup,
    ad_group_index: index
  }
}));

