// Extract ad group ID and prepare for keyword/ad creation
const response = $json;
const previousData = $('Split into Ad Groups').item.json;

let adGroupId = '';
if (response.results && response.results[0] && response.results[0].resourceName) {
  const match = response.results[0].resourceName.match(/adGroups\/(\d+)/);
  if (match) {
    adGroupId = match[1];
  }
}

if (!adGroupId) {
  throw new Error('Failed to extract ad group ID');
}

console.log('Created ad group:', previousData.current_ad_group.name, '- ID:', adGroupId);

return {
  json: {
    ...previousData,
    ad_group_id: adGroupId
  }
};

// Create keywords for this ad group
const data = $json;
const keywords = data.current_ad_group.keywords || [];

const operations = keywords.map(kw => ({
  create: {
    adGroup: `customers/${data.account_id_clean}/adGroups/${data.ad_group_id}`,
    status: 'ENABLED',
    keyword: {
      text: kw.text,
      matchType: kw.match_type
    }
  }
}));

console.log(`Creating ${operations.length} keywords in ad group ${data.current_ad_group.name}`);

return {
  json: {
    ...data,
    keyword_operations: { operations },
    api_endpoint: `https://googleads.googleapis.com/v22/customers/${data.account_id_clean}/adGroupCriteria:mutate`
  }
};

// Create responsive search ads for this ad group
const previousData = $('Extract Ad Group ID').item.json;
const ads = previousData.current_ad_group.ads || [];

const operations = ads.map(ad => ({
  create: {
    adGroup: `customers/${previousData.account_id_clean}/adGroups/${previousData.ad_group_id}`,
    status: 'ENABLED',
    ad: {
      responsiveSearchAd: {
        headlines: ad.headlines.map(h => ({ text: h })),
        descriptions: ad.descriptions.map(d => ({ text: d }))
      },
      finalUrls: [ad.final_url]
    }
  }
}));

console.log(`Creating ${operations.length} RSAs in ad group ${previousData.current_ad_group.name}`);

return {
  json: {
    ...previousData,
    ad_operations: { operations },
    api_endpoint: `https://googleads.googleapis.com/v22/customers/${previousData.account_id_clean}/adGroupAds:mutate`
  }
};

// Get campaign data (from first ad group)
const aggregatedData = $json.data[0];

return {
  json: {
    account_id: aggregatedData.account_id,
    account_id_clean: aggregatedData.account_id_clean,
    account_name: aggregatedData.account_name,
    manager_id: aggregatedData.manager_id,
    campaign_id: aggregatedData.campaign_id,
    parsed_campaign: aggregatedData.parsed_campaign,
    row_number: aggregatedData.row_number
  }
};

// Create campaign-level negative keywords
const data = $json;
const negatives = data.parsed_campaign.negative_keywords || [];

const operations = negatives.map(neg => ({
  create: {
    campaign: `customers/${data.account_id_clean}/campaigns/${data.campaign_id}`,
    keyword: {
      text: neg.text,
      matchType: neg.match_type
    },
    negative: true
  }
}));

console.log(`Creating ${operations.length} campaign-level negative keywords`);

return {
  json: {
    ...data,
    negative_operations: { operations },
    api_endpoint: `https://googleads.googleapis.com/v22/customers/${data.account_id_clean}/campaignCriteria:mutate`
  }
};
